{
  "id": 1,
  "jsonrpc": "2.0",
  "result": {
    "tools": [
      {
        "description": "Ask for approval of a tool call that needs a permission prompt.",
        "inputSchema": {
          "properties": {
            "input": {
              "type": "object"
            },
            "tool_name": {
              "type": "string"
            },
            "tool_use_id": {
              "type": "string"
            }
          },
          "required": [
            "tool_name",
            "input"
          ],
          "type": "object"
        },
        "name": "approve"
      },
      {
        "description": "Ask the owner for a folder, file or website your sandbox blocks (a command failed with \"Operation not permitted\", or the network was refused). Give the absolute path, or the host name, and why. The answer comes at your next turn: after this call, end your turn and say what you are waiting for.",
        "inputSchema": {
          "properties": {
            "domain": {
              "description": "host name, e.g. pypi.org",
              "type": "string"
            },
            "path": {
              "description": "absolute path of the file or folder",
              "type": "string"
            },
            "reason": {
              "type": "string"
            },
            "write": {
              "description": "also write there (default: read only)",
              "type": "boolean"
            }
          },
          "required": [
            "reason"
          ],
          "type": "object"
        },
        "name": "request_access"
      },
      {
        "description": "Report a bug in Kith itself (not in the person's own work). Give a short title and what happened. It is scrubbed of secrets and personal details, shown to the owner on a card, and filed on GitHub only if they say yes. Tell the person what you reported and that it waits on the owner.",
        "inputSchema": {
          "properties": {
            "details": {
              "description": "what happened, what you expected",
              "type": "string"
            },
            "title": {
              "type": "string"
            }
          },
          "required": [
            "title"
          ],
          "type": "object"
        },
        "name": "report_bug"
      },
      {
        "description": "Ask the owner for a key or token of a service you need (one the service declares) and are not allowed to use yet. The owner picks an existing account or types the key into a card; you never see it. The answer comes at your next turn: after this call, end your turn and say what you are waiting for.",
        "inputSchema": {
          "properties": {
            "purpose": {
              "description": "what you need it for",
              "type": "string"
            },
            "service": {
              "description": "service name, e.g. github",
              "type": "string"
            }
          },
          "required": [
            "service",
            "purpose"
          ],
          "type": "object"
        },
        "name": "request_secret"
      }
    ]
  }
}
